mapper.select:
SELECT id, service_name, event_outbox_id, error_msg, retry_count, retry_last_time, retry_after_time,
       create_time, create_by, update_time, update_by, delete_time, delete_by
FROM sys_event_outbox_dlq
WHERE service_name = #{serviceName}
  AND delete_time IS NULL

  AND retry_count < #{maxRetry}


  AND 1 = 0

  AND retry_after_time IS NULL
ORDER BY create_time ASC
LIMIT #{limit}

SELECT id, service_name, event_outbox_id, error_msg, retry_count, retry_last_time, retry_after_time,
       create_time, create_by, update_time, update_by, delete_time, delete_by
FROM sys_event_outbox_dlq
WHERE service_name = #{serviceName}
  AND delete_time IS NULL

  AND retry_count < #{maxRetry}


  AND 1 = 0

  AND retry_after_time <= #{now}
ORDER BY retry_after_time ASC, create_time ASC
LIMIT #{limit}

mapper.update:
UPDATE sys_event_outbox_dlq
SET retry_after_time = #{claimUntil},
    update_time = #{updateTime}
WHERE id = #{id}
  AND delete_time IS NULL
  AND (retry_after_time IS NULL OR retry_after_time <= #{now})

UPDATE sys_event_outbox_dlq
SET retry_count = 0,
    retry_last_time = NULL,
    retry_after_time = NULL,
    error_msg = CASE
        WHEN error_msg LIKE '[EXHAUSTED] %' THEN SUBSTRING(error_msg, 13)
        ELSE error_msg
    END,
    update_time = #{updateTime}
WHERE service_name = #{serviceName}
  AND create_time >= #{from}
  AND create_time <= #{to}
  AND delete_time IS NULL
